import{_ as i,a0 as r,w as o,s as g,ao as l,I as p,x as n,a1 as t,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Python 學習：urllib 簡介 | LCTT x X-CMD","titleTemplate":false,"description":"Python 學習：urllib 簡介 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 學習：urllib 簡介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 學習：urllib 簡介 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160628 Python 101 An Intro to urllib","title":"Python 學習：urllib 簡介","tag":"201608","desc":""},"relativePath":"201608/20160628 Python 101 An Intro to urllib.md","filePath":"[post].md"}'),u={name:"201608/20160628 Python 101 An Intro to urllib.md"};function h(b,s,c,d,k,m){const a=r("Link");return o(),g("div",null,[s[16]||(s[16]=l(`<h1 id="python-學習-urllib-簡介" tabindex="-1">Python 學習：urllib 簡介 <a class="header-anchor" href="#python-學習-urllib-簡介" aria-label="Permalink to “Python 學習：urllib 簡介”">​</a></h1><p>Python 3 的 urllib 模組是一堆可以處理 URL 的組件集合。如果你有 Python 2 的知識，那麼你就會注意到 Python 2 中有 urllib 和 urllib2 兩個版本的模組。這些現在都是 Python 3 的 urllib 包的一部分。當前版本的 urllib 包括下面幾部分：</p><ul><li>urllib.request</li><li>urllib.error</li><li>urllib.parse</li><li>urllib.rebotparser</li></ul><p>接下來我們會分開討論除了 urllib.error 以外的幾部分。官方文檔實際推薦你嘗試第三方庫， requests，一個高級的 HTTP 客户端接口。然而我依然認為知道如何不依賴第三方庫打開 URL 並與之進行交互是很有用的，而且這也可以幫助你理解為什麼 requests 包是如此的流行。</p><h3 id="urllib-request" tabindex="-1">urllib.request <a class="header-anchor" href="#urllib-request" aria-label="Permalink to “urllib.request”">​</a></h3><p>urllib.request 模組期初是用來打開和獲取 URL 的。讓我們看看你可以用函數 urlopen 可以做的事：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.request</span></span>
<span class="line"><span>&gt;&gt;&gt; url = urllib.request.urlopen(&#39;https://www.google.com/&#39;)</span></span>
<span class="line"><span>&gt;&gt;&gt; url.geturl()</span></span>
<span class="line"><span>&#39;https://www.google.com/&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; url.info()</span></span>
<span class="line"><span>&lt;http.client.HTTPMessage object at 0x7fddc2de04e0&gt;</span></span>
<span class="line"><span>&gt;&gt;&gt; header = url.info()</span></span>
<span class="line"><span>&gt;&gt;&gt; header.as_string()</span></span>
<span class="line"><span>(&#39;Date: Fri, 24 Jun 2016 18:21:19 GMT\\n&#39;</span></span>
<span class="line"><span> &#39;Expires: -1\\n&#39;</span></span>
<span class="line"><span> &#39;Cache-Control: private, max-age=0\\n&#39;</span></span>
<span class="line"><span> &#39;Content-Type: text/html; charset=ISO-8859-1\\n&#39;</span></span>
<span class="line"><span> &#39;P3P: CP=&quot;This is not a P3P policy! See &#39;</span></span>
<span class="line"><span> &#39;https://www.google.com/support/accounts/answer/151657?hl=en for more info.&quot;\\n&#39;</span></span>
<span class="line"><span> &#39;Server: gws\\n&#39;</span></span>
<span class="line"><span> &#39;X-XSS-Protection: 1; mode=block\\n&#39;</span></span>
<span class="line"><span> &#39;X-Frame-Options: SAMEORIGIN\\n&#39;</span></span>
<span class="line"><span> &#39;Set-Cookie: &#39;</span></span>
<span class="line"><span> &#39;NID=80=tYjmy0JY6flsSVj7DPSSZNOuqdvqKfKHDcHsPIGu3xFv41LvH_Jg6LrUsDgkPrtM2hmZ3j9V76pS4K_cBg7pdwueMQfr0DFzw33SwpGex5qzLkXUvUVPfe9g699Qz4cx9ipcbU3HKwrRYA; &#39;</span></span>
<span class="line"><span> &#39;expires=Sat, 24-Dec-2016 18:21:19 GMT; path=/; domain=.google.com; HttpOnly\\n&#39;</span></span>
<span class="line"><span> &#39;Alternate-Protocol: 443:quic\\n&#39;</span></span>
<span class="line"><span> &#39;Alt-Svc: quic=&quot;:443&quot;; ma=2592000; v=&quot;34,33,32,31,30,29,28,27,26,25&quot;\\n&#39;</span></span>
<span class="line"><span> &#39;Accept-Ranges: none\\n&#39;</span></span>
<span class="line"><span> &#39;Vary: Accept-Encoding\\n&#39;</span></span>
<span class="line"><span> &#39;Connection: close\\n&#39;</span></span>
<span class="line"><span> &#39;\\n&#39;)</span></span>
<span class="line"><span>&gt;&gt;&gt; url.getcode()</span></span>
<span class="line"><span>200</span></span></code></pre></div><p>在這裏我們包含了需要的模組，然後告訴它打開 Google 的 URL。現在我們就有了一個可以交互的 HTTPResponse 對象。我們要做的第一件事是調用方法 geturl ，它會返回根據 URL 獲取的資源。這可以讓我們發現 URL 是否進行了重定向。</p><p>接下來調用 info ，它會返回網頁的元數據，比如請求頭信息。因此，我們可以將結果賦給我們的 headers 變量，然後調用它的方法 as_string 。就可以打印出我們從 Google 收到的頭信息。你也可以通過 getcode 得到網頁的 HTTP 響應碼，當前情況下就是 200，意思是正常工作。</p><p>如果你想看看網頁的 HTML 代碼，你可以調用變量 url 的方法 read。我不準備再現這個過程，因為輸出結果太長了。</p><p>請注意 request 對象默認發起 GET 請求，除非你指定了它的 data 參數。如果你給它傳遞了 data 參數，這樣 request 對象將會變成 POST 請求。</p><hr><h3 id="下載文件" tabindex="-1">下載文件 <a class="header-anchor" href="#下載文件" aria-label="Permalink to “下載文件”">​</a></h3><p>urllib 一個典型的應用場景是下載文件。讓我們看看幾種可以完成這個任務的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.request</span></span>
<span class="line"><span>&gt;&gt;&gt; url = &#39;http://www.blog.pythonlibrary.org/wp-content/uploads/2012/06/wxDbViewer.zip&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; response = urllib.request.urlopen(url)</span></span>
<span class="line"><span>&gt;&gt;&gt; data = response.read()</span></span>
<span class="line"><span>&gt;&gt;&gt; with open(&#39;/home/mike/Desktop/test.zip&#39;, &#39;wb&#39;) as fobj:</span></span>
<span class="line"><span>...     fobj.write(data)</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>這個例子中我們打開一個保存在我的Blog上的 zip 壓縮文件的 URL。然後我們讀出數據並將數據寫到磁盤。一個替代此操作的方案是使用 urlretrieve ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.request</span></span>
<span class="line"><span>&gt;&gt;&gt; url = &#39;http://www.blog.pythonlibrary.org/wp-content/uploads/2012/06/wxDbViewer.zip&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; tmp_file, header = urllib.request.urlretrieve(url)</span></span>
<span class="line"><span>&gt;&gt;&gt; with open(&#39;/home/mike/Desktop/test.zip&#39;, &#39;wb&#39;) as fobj:</span></span>
<span class="line"><span>...     with open(tmp_file, &#39;rb&#39;) as tmp:</span></span>
<span class="line"><span>...         fobj.write(tmp.read())</span></span></code></pre></div><p>方法 urlretrieve 會把網絡對象拷貝到本地文件。除非你在使用 urlretrieve 的第二個參數指定你要保存文件的路徑，否則這個文件將被拷貝到臨時文件夾的隨機命名的一個文件中。這個可以為你節省一步操作，並且使代碼看起來更簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.request</span></span>
<span class="line"><span>&gt;&gt;&gt; url = &#39;http://www.blog.pythonlibrary.org/wp-content/uploads/2012/06/wxDbViewer.zip&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; urllib.request.urlretrieve(url, &#39;/home/mike/Desktop/blog.zip&#39;)</span></span>
<span class="line"><span>(&#39;/home/mike/Desktop/blog.zip&#39;,</span></span>
<span class="line"><span> &lt;http.client.HTTPMessage object at 0x7fddc21c2470&gt;)</span></span></code></pre></div><p>如你所見，它返回了文件保存的路徑，以及從請求得來的頭信息。</p><h3 id="設置你的用户代理" tabindex="-1">設置你的用户代理 <a class="header-anchor" href="#設置你的用户代理" aria-label="Permalink to “設置你的用户代理”">​</a></h3><p>當你使用瀏覽器訪問網頁時，瀏覽器會告訴網站它是誰。這就是所謂的 user-agent （用户代理）字段。Python 的 urllib 會表示它自己為 Python-urllib/x.y ， 其中 x 和 y 是你使用的 Python 的主、次版本號。有一些網站不認識這個用户代理字段，然後網站可能會有奇怪的表現或者根本不能正常工作。辛運的是你可以很輕鬆的設置你自己的 user-agent 字段。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.request</span></span>
<span class="line"><span>&gt;&gt;&gt; user_agent = &#39; Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:47.0) Gecko/20100101 Firefox/47.0&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; url = &#39;http://www.whatsmyua.com/&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; headers = {&#39;User-Agent&#39;: user_agent}</span></span>
<span class="line"><span>&gt;&gt;&gt; request = urllib.request.Request(url, headers=headers)</span></span>
<span class="line"><span>&gt;&gt;&gt; with urllib.request.urlopen(request) as response:</span></span>
<span class="line"><span>...     with open(&#39;/home/mdriscoll/Desktop/user_agent.html&#39;, &#39;wb&#39;) as out:</span></span>
<span class="line"><span>...         out.write(response.read())</span></span></code></pre></div>`,23)),p("p",null,[s[1]||(s[1]=n("這裏設置我們的用户代理為 Mozilla FireFox ，然後我們訪問 ",-1)),t(a,{href:"http://www.whatsmyua.com/"},{default:e(()=>[...s[0]||(s[0]=[n("http://www.whatsmyua.com/",-1)])]),_:1}),s[2]||(s[2]=n(" ， 它會告訴我們它識別出的我們的 user-agent 字段。之後我們將 url 和我們的頭信息傳給 urlopen 創建一個 Request 實例。最後我們保存這個結果。如果你打開這個結果，你會看到我們成功的修改了自己的 user-agent 字段。使用這段代碼盡情的嘗試不同的值來看看它是如何改變的。",-1))]),s[17]||(s[17]=l(`<hr><h3 id="urllib-parse" tabindex="-1">urllib.parse <a class="header-anchor" href="#urllib-parse" aria-label="Permalink to “urllib.parse”">​</a></h3><p>urllib.parse 庫是用來拆分和組合 URL 字符串的標準接口。比如，你可以使用它來轉換一個相對的 URL 為絕對的 URL。讓我們試試用它來轉換一個包含查詢的 URL ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; from urllib.parse import urlparse</span></span>
<span class="line"><span>&gt;&gt;&gt; result = urlparse(&#39;https://duckduckgo.com/?q=python+stubbing&amp;t=canonical&amp;ia=qa&#39;)</span></span>
<span class="line"><span>&gt;&gt;&gt; result</span></span>
<span class="line"><span>ParseResult(scheme=&#39;https&#39;, netloc=&#39;duckduckgo.com&#39;, path=&#39;/&#39;, params=&#39;&#39;, query=&#39;q=python+stubbing&amp;t=canonical&amp;ia=qa&#39;, fragment=&#39;&#39;)</span></span>
<span class="line"><span>&gt;&gt;&gt; result.netloc</span></span>
<span class="line"><span>&#39;duckduckgo.com&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; result.geturl()</span></span>
<span class="line"><span>&#39;https://duckduckgo.com/?q=python+stubbing&amp;t=canonical&amp;ia=qa&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; result.port</span></span>
<span class="line"><span>None</span></span></code></pre></div><p>這裏我們導入了函數 urlparse ， 並且把一個包含搜索查詢字串的 duckduckgo 的 URL 作為參數傳給它。我的查詢字串是搜索關於 “python stubbing” 的文章。如你所見，它返回了一個 ParseResult 對象，你可以用這個對象瞭解更多關於 URL 的信息。舉個例子，你可以獲取到端口信息（本例中沒有端口信息）、網絡位置、路徑和很多其它東西。</p><h3 id="提交一個-web-表單" tabindex="-1">提交一個 Web 表單 <a class="header-anchor" href="#提交一個-web-表單" aria-label="Permalink to “提交一個 Web 表單”">​</a></h3><p>這個模組還有一個方法 urlencode 可以向 URL 傳輸數據。 urllib.parse 的一個典型使用場景是提交 Web 表單。讓我們通過搜索引擎 duckduckgo 搜索 Python 來看看這個功能是怎麼工作的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.request</span></span>
<span class="line"><span>&gt;&gt;&gt; import urllib.parse</span></span>
<span class="line"><span>&gt;&gt;&gt; data = urllib.parse.urlencode({&#39;q&#39;: &#39;Python&#39;})</span></span>
<span class="line"><span>&gt;&gt;&gt; data</span></span>
<span class="line"><span>&#39;q=Python&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; url = &#39;http://duckduckgo.com/html/&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; full_url = url + &#39;?&#39; + data</span></span>
<span class="line"><span>&gt;&gt;&gt; response = urllib.request.urlopen(full_url)</span></span>
<span class="line"><span>&gt;&gt;&gt; with open(&#39;/home/mike/Desktop/results.html&#39;, &#39;wb&#39;) as f:</span></span>
<span class="line"><span>...     f.write(response.read())</span></span></code></pre></div><p>這個例子很直接。基本上我們是使用 Python 而不是瀏覽器向 duckduckgo 提交了一個查詢。要完成這個我們需要使用 urlencode 構建我們的查詢字符串。然後我們把這個字符串和網址拼接成一個完整的正確 URL ，然後使用 urllib.request 提交這個表單。最後我們就獲取到了結果然後保存到磁盤上。</p><hr><h3 id="urllib-robotparser" tabindex="-1">urllib.robotparser <a class="header-anchor" href="#urllib-robotparser" aria-label="Permalink to “urllib.robotparser”">​</a></h3><p>robotparser 模組是由一個單獨的類 RobotFileParser 構成的。這個類會回答諸如一個特定的用户代理是否獲取已經設置了 robot.txt 的網站的 URL。 robot.txt 文件會告訴網絡爬蟲或者機器人當前網站的那些部分是不允許被訪問的。讓我們看一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import urllib.robotparser</span></span>
<span class="line"><span>&gt;&gt;&gt; robot = urllib.robotparser.RobotFileParser()</span></span>
<span class="line"><span>&gt;&gt;&gt; robot.set_url(&#39;http://arstechnica.com/robots.txt&#39;)</span></span>
<span class="line"><span>None</span></span>
<span class="line"><span>&gt;&gt;&gt; robot.read()</span></span>
<span class="line"><span>None</span></span>
<span class="line"><span>&gt;&gt;&gt; robot.can_fetch(&#39;*&#39;, &#39;http://arstechnica.com/&#39;)</span></span>
<span class="line"><span>True</span></span>
<span class="line"><span>&gt;&gt;&gt; robot.can_fetch(&#39;*&#39;, &#39;http://arstechnica.com/cgi-bin/&#39;)</span></span>
<span class="line"><span>False</span></span></code></pre></div><p>這裏我們導入了 robot 分析器類，然後創建一個實例。然後我們給它傳遞一個表明網站 robots.txt 位置的 URL 。接下來我們告訴分析器來讀取這個文件。完成後，我們給它了一組不同的 URL 讓它找出那些我們可以爬取而那些不能爬取。我們很快就看到我們可以訪問主站但是不能訪問 cgi-bin 路徑。</p><hr><h3 id="總結一下" tabindex="-1">總結一下 <a class="header-anchor" href="#總結一下" aria-label="Permalink to “總結一下”">​</a></h3><p>現在你就有能力使用 Python 的 urllib 包了。在這一節裏，我們學習瞭如何下載文件、提交 Web 表單、修改自己的用户代理以及訪問 robots.txt。 urllib 還有一大堆附加功能沒有在這裏提及，比如網站身份認證。你可能會考慮在使用 urllib 進行身份認證之前切換到 requests 庫，因為 requests 已經以更易用和易調試的方式實現了這些功能。我同時也希望提醒你 Python 已經通過 http.cookies 模組支持 Cookies 了，雖然在 request 包裏也很好的封裝了這個功能。你應該可能考慮同時試試兩個來決定那個最適合你。</p><hr>`,18)),p("p",null,[s[4]||(s[4]=n("via: ",-1)),t(a,{href:"http://www.blog.pythonlibrary.org/2016/06/28/python-101-an-intro-to-urllib/"},{default:e(()=>[...s[3]||(s[3]=[n("http://www.blog.pythonlibrary.org/2016/06/28/python-101-an-intro-to-urllib/",-1)])]),_:1})]),p("p",null,[s[8]||(s[8]=n("作者：",-1)),t(a,{href:"http://www.blog.pythonlibrary.org/author/mld/"},{default:e(()=>[...s[5]||(s[5]=[n("Mike",-1)])]),_:1}),s[9]||(s[9]=n(" 譯者：",-1)),t(a,{href:"https://github.com/oska874"},{default:e(()=>[...s[6]||(s[6]=[n("Ezio",-1)])]),_:1}),s[10]||(s[10]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[13]||(s[13]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[11]||(s[11]=[n("LCTT",-1)])]),_:1}),s[14]||(s[14]=n(" 原創翻譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...s[12]||(s[12]=[n("Linux中國",-1)])]),_:1}),s[15]||(s[15]=n(" 榮譽推出",-1))])])}const P=i(u,[["render",h]]);export{w as __pageData,P as default};
